window.AUTH=window.AUTH||{};window.AUTH["18-489"]={"d":"18-489","id":"2018/18-489","n":"Taggart v. Lorenzen","briefs":[{"k":"petitioner","label":"Brief of petitioner Bradley Weston Taggart","date":"2019-02-19","url":"https://www.supremecourt.gov/DocketPDF/18/18-489/88898/20190219230605075_18-489%20ts.pdf","side":"pet","n":23},{"k":"united-states","label":"Brief amicus curiae of United States in support of neither party","date":"2019-02-26","url":"https://www.supremecourt.gov/DocketPDF/18/18-489/89762/20190226171126911_18-489npUnitedStates.pdf","side":"us","n":79},{"k":"respondent","label":"Brief of respondents Shelley Lorenzen, et al.","date":"2019-03-21","url":"https://www.supremecourt.gov/DocketPDF/18/18-489/92771/20190321210116011_18-489bs.pdf","side":"res","n":110},{"k":"reply","label":"Reply of petitioner Bradley Weston Taggart","date":"2019-04-17","url":"https://www.supremecourt.gov/DocketPDF/18/18-489/96803/20190417135520162_18-489%20rb.pdf","side":"pet","n":22}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/18-489_p8k0.pdf","tr":true,"items":[{"t":"case","label":"Bessette v. Avco Fin. Servs., Inc.","cite":"230 F.3d 439","y":2000,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/230/439/","by":{"0":"4, 5, 19, 23"}},{"t":"case","label":"Espinosa v. United Student Aid Funds, Inc.","cite":"553 F.3d 1193","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/553/1193/","by":{"0":"5"}},{"t":"case","label":"Food Lion, Inc. v. United Food & Commercial Workers Int’l Union, AFL-CIO-CLC","cite":"103 F.3d 1007","y":1997,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/103/1007/","by":{"0":"16","1":"22"}},{"t":"case","label":"Grogan v. Garner","cite":"498 U.S. 279","y":1991,"id":"1990/89-1149","sc":1,"sum":"Courts should apply the \"preponderance of the evidence\" standard. Justice John Paul Stevens, for a unanimous Supreme Court, wrote that the lack of a specified standard of evidence in section 523(a) implied that Congress had intended the preponderance of the evidence standard to be used.","sumSrc":"Oyez","by":{"0":"4","2":"43","3":"10"}},{"t":"case","label":"Harley-Davidson, Inc. v. Morris","cite":"19 F.3d 142","y":1994,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/19/142/","sum":"Recognizing that “a good faith and reasonable interpretation of a court order” can preclude contempt.","sumSrc":"brief:2","by":{"0":"16","2":"26"}},{"t":"case","label":"Howard Johnson Co. v. Khimani","cite":"892 F.2d 1512","y":1990,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/892/1512/","by":{"0":"20"}},{"t":"case","label":"IRS v. Murphy","cite":"892 F.3d 29","y":2018,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/892/29/","by":{"0":"25","2":"42","3":"12"}},{"t":"case","label":"Jerman v. Carlisle, McNellie, Rini, Kramer & Ulrich LPA","cite":"559 U.S. 573","y":2010,"id":"2009/08-1200","sc":1,"sum":"The Court held that a debt collector's mistake in interpreting the law cannot qualify for the Fair Debt Collection Practices Act bona fide error defense.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"Jove Eng’g, Inc. v. IRS","cite":"92 F.3d 1539","y":1996,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/92/1539/","by":{"0":"passim","1":"17, 18","2":"4, 35"}},{"t":"case","label":"Local Loan Co. v. Hunt","cite":"292 U.S. 234","y":1934,"id":"scdb/1933-054","sc":1,"sum":"1. A court of bankruptcy has jurisdiction by ancillary proceedings to enforce an order of discharge by enjoining the prosecution of suits brought against the debtor.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"McComb v. Jacksonville Paper Co.","cite":"336 U.S. 187","y":1949,"id":"scdb/1948-037","sc":1,"op":2,"ar":7,"sum":"A decree of the District Court in a proceeding under the Fair Labor Standards Act enjoined respondents from violating the minimum wage, overtime, and record-keeping provisions of the Act. Respondents took no appeal. Three years later the Administrator instituted a civil contempt proceeding alleging violations of the decree and praying that respondents, in order to purge themselves of contempt, be required to make …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"11, 22, 25, 26","2":"passim","3":"passim"}},{"t":"case","label":"SEC v. McNamee","cite":"481 F.3d 451","y":2007,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/481/451/","by":{"0":"16"}},{"t":"case","label":"Walls v. Wells Fargo Bank, N.A.","cite":"276 F.3d 502","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/276/502/","by":{"0":"21"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","subs":["(5)(A)","(12)"],"stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"head":"§101. Definitions","tname":"Bankruptcy","by":{"0":"passim","1":"30, 30","2":"47, 47","3":"passim"}},{"t":"usc","label":"11 U.S.C. § 105","url":"https://www.law.cornell.edu/uscode/text/11/105","subs":["(a)"],"stext":{"head":"§105. Power of court","paras":[[0,"(a) The court may issue any order, process, or judgment that is necessary or appropriate to carry out the provisions of this title. No provision of this title providing for the raising of an issue by a party in interest shall be construed to preclude the court from, sua sponte, taking any action or making any determination necessary or appropriate to enforce or implement court orders or rules, or to prevent an abuse of process."],[0,"(b) Notwithstanding subsection (a) of this section, a court may not appoint a receiver in a case under this title."],[0,"(c) The ability of any district judge or other officer or employee of a district court to exercise any of the authority or responsibilities conferred upon the court under this title shall be determined by reference to the provisions relating to such judge, officer, or employee set forth in title 28. This subsection shall not be interpreted to exclude bankruptcy judges and other officers or employees appointed pursuant to chapter 6 of title 28 from its operation."],[0,"(d) The court, on its own motion or on the request of a party in interest—"],[1,"(1) shall hold such status conferences as are necessary to further the expeditious and economical resolution of the case; and"],[1,"(2) unless inconsistent with another provision of this title or with applicable Federal Rules of Bankruptcy Procedure, may issue an order at any such conference prescribing such limitations and conditions as the court deems appropriate to ensure that the case is handled expeditiously and economically, including an order that—"],[2,"(A) sets the date by which the trustee must assume or reject an executory contract or unexpired lease; or"],[2,"(B) in a case under chapter 11 of this title—"],[3,"(i) sets a date by which the debtor, or trustee if one has been appointed, shall file a disclosure statement and plan;"],[3,"(ii) sets a date by which the debtor, or trustee if one has been appointed, shall solicit acceptances of a plan;"],[3,"(iii) sets the date by which a party in interest other than a debtor may file a plan;"],[3,"(iv) sets a date by which a proponent of a plan, other than the debtor, shall solicit acceptances of such plan;"],[3,"(v) fixes the scope and format of the notice to be provided regarding the hearing on approval of the disclosure statement; or"],[3,"(vi) provides that the hearing on approval of the disclosure statement may be combined with the hearing on confirmation of the plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/105?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":7,"head":"§105. Power of court","tname":"Bankruptcy","by":{"0":"passim","1":"4, 5, 4, 13, 14, 23","2":"passim","3":"passim"}},{"t":"usc","label":"11 U.S.C. § 362","url":"https://www.law.cornell.edu/uscode/text/11/362","subs":["(k)","(k)(2)","(a)","(k)(1)","(c)(3)","(c)(4)","(n)(1)"],"stext":{"head":"§362. Automatic stay","paras":[[0,"(a) Except as provided in subsection (b) of this section, a petition filed under section 301, 302, or 303 of this title, or an application filed under section 5(a)(3) of the Securities Investor Protection Act of 1970, operates as a stay, applicable to all entities, of—"],[1,"(1) the commencement or continuation, including the issuance or employment of process, of a judicial, administrative, or other action or proceeding against the debtor that was or could have been commenced before the commencement of the case under this title, or to recover a claim against the debtor that arose before the commencement of the case under this title;"],[1,"(2) the enforcement, against the debtor or against property of the estate, of a judgment obtained before the commencement of the case under this title;"],[1,"(3) any act to obtain possession of property of the estate or of property from the estate or to exercise control over property of the estate;"],[1,"(4) any act to create, perfect, or enforce any lien against property of the estate;"],[1,"(5) any act to create, perfect, or enforce against property of the debtor any lien to the extent that such lien secures a claim that arose before the commencement of the case under this title;"],[1,"(6) any act to collect, assess, or recover a claim against the debtor that arose before the commencement of the case under this title;"],[1,"(7) the setoff of any debt owing to the debtor that arose before the commencement of the case under this title against any claim against the debtor; and"],[1,"(8) the commencement or continuation of a proceeding before the United States Tax Court concerning a tax liability of a debtor that is a corporation for a taxable period the bankruptcy court may determine or concerning the tax liability of a debtor who is an individual for a taxable period ending before the date of the order for relief under this title."],[0,"(b) The filing of a petition under section 301, 302, or 303 of this title, or of an application under section 5(a)(3) of the Securities Investor Protection Act of 1970, does not operate as a stay—"],[1,"(1) under subsection (a) of this section, of the commencement or continuation of a criminal action or proceeding against the debtor;"],[1,"(2) under subsection (a)—"],[2,"(A) of the commencement or continuation of a civil action or proceeding—"],[3,"(i) for the establishment of paternity;"],[3,"(ii) for the establishment or modification of an order for domestic support obligations;"],[3,"(iii) concerning child custody or visitation;"],[3,"(iv) for the dissolution of a marriage, except to the extent that such proceeding seeks to determine the division of property that is property of the estate; or"],[3,"(v) regarding domestic violence;"],[2,"(B) of the collection of a domestic support obligation from property that is not property of the estate;"],[2,"(C) with respect to the withholding of income that is property of the estate or property of the debtor for payment of a domestic support obligation under a judicial or administrative order or a statute;"],[2,"(D) of the withholding, suspension, or restriction of a driver's license, a professional or occupational license, or a recreational license, under State law, as specified in section 466(a)(16) of the Social Security Act;"],[2,"(E) of the reporting of overdue support owed by a parent to any consumer reporting agency as specified in section 466(a)(7) of the Social Security Act;"],[2,"(F) of the interception of a tax refund, as specified in sections 464 and 466(a)(3) of the Social Security Act or under an analogous State law; or"],[2,"(G) of the enforcement of a medical obligation, as specified under title IV of the Social Security Act;"],[1,"(3) under subsection (a) of this section, of any act to perfect, or to maintain or continue the perfection of, an interest in property to the extent that the trustee's rights and powers are subject to such perfection under section 546(b) of this title or to the extent that such act is accomplished within the period provided under section 547(e)(2)(A) of this title;"],[1,"(4) under paragraph (1), (2), (3), or (6) of subsection (a) of this section, of the commencement or continuation of an action or proceeding by a governmental unit or any organization exercising authority under the Convention on the Prohibition of the Development, Production, Stockpiling and Use of Chemical Weapons and on Their Destruction, opened for signature on January 13, 1993, to enforce such governmental unit's or organization's police and regulatory power, including the enforcement of a judgment other than a money judgment, obtained in an action or proceeding by the governmental unit to enforce such governmental unit's or organization's police or regulatory power;"],[1,"[(5) Repealed. Pub. L. 105–277, div. I, title VI, §603(1), Oct. 21, 1998, 112 Stat. 2681–866;]"],[1,"(6) under subsection (a) of this section, of the exercise by a commodity broker, forward contract merchant, stockbroker, financial institution, financial participant, or securities clearing agency of any contractual right (as defined in section 555 or 556) under any security agreement or arrangement or other credit enhancement forming a part of or related to any commodity contract, forward contract or securities contract, or of any contractual right (as defined in section 555 or 556) to offset or net out any termination value, payment amount, or other transfer obligation arising under or in connection with 1 or more such contracts, including any master agreement for such contracts;"],[1,"(7) under subsection (a) of this section, of the exercise by a repo participant or financial participant of any contractual right (as defined in section 559) under any security agreement or arrangement or other credit enhancement forming a part of or related to any repurchase agreement, or of any contractual right (as defined in section 559) to offset or net out any termination value, payment amount, or other transfer obligation arising under or in connection with 1 or more such agreements, including any master agreement for such agreements;"],[1,"(8) under subsection (a) of this section, of the commencement of any action by the Secretary of Housing and Urban Development to foreclose a mortgage or deed of trust in any case in which the mortgage or deed of trust held by the Secretary is insured or was formerly insured under the National Housing Act and covers property, or combinations of property, consisting of five or more living units;"],[1,"(9) under subsection (a), of—"],[2,"(A) an audit by a governmental unit to determine tax liability;"],[2,"(B) the issuance to the debtor by a governmental unit of a notice of tax deficiency;"],[2,"(C) a demand for tax returns; or"],[2,"(D) the making of an assessment for any tax and issuance of a notice and demand for payment of such an assessment (but any tax lien that would otherwise attach to property of the estate by reason of such an assessment shall not take effect unless such tax is a debt of the debtor that will not be discharged in the case and such property or its proceeds are transferred out of the estate to, or otherwise revested in, the debtor)."],[1,"(10) under subsection (a) of this section, of any act by a lessor to the debtor under a lease of nonresidential real property that has terminated by the expiration of the stated term of the lease before the commencement of or during a case under this title to obtain possession of such property;"],[1,"(11) under subsection (a) of this section, of the presentment of a negotiable instrument and the giving of notice of and protesting dishonor of such an instrument;"],[1,"(12) under subsection (a) of this section, after the date which is 90 days after the filing of such petition, of the commencement or continuation, and conclusion to the entry of final judgment, of an action which involves a debtor subject to reorganization pursuant to chapter 11 of this title and which was brought by the Secretary of Transportation under section 31325 of title 46 (including distribution of any proceeds of sale) to foreclose a preferred ship or fleet mortgage, or a security interest in or relating to a vessel or vessel under construction, held by the Secretary of Transportation under chapter 537 of title 46 or section 109(h) of title 49, or under applicable State law;"],[1,"(13) under subsection (a) of this section, after the date which is 90 days after the filing of such petition, of the commencement or continuation, and conclusion to the entry of final judgment, of an action which involves a debtor subject to reorganization pursuant to chapter 11 of this title and which was brought by the Secretary of Commerce under section 31325 of title 46 (including distribution of any proceeds of sale) to foreclose a preferred ship or fleet mortgage in a vessel or a mortgage, deed of trust, or other security interest in a fishing facility held by the Secretary of Commerce under chapter 537 of title 46;"],[1,"(14) under subsection (a) of this section, of any action by an accrediting agency regarding the accreditation status of the debtor as an educational institution;"],[1,"(15) under subsection (a) of this section, of any action by a State licensing body regarding the licensure of the debtor as an educational institution;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/362?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§362. Automatic stay","tname":"Bankruptcy","by":{"0":"12, 21, 25, 21, 25","1":"5, 5, 10, 23, 5","2":"3, 30, 30, 5, 13, 39, 41, 30, 42, 30","3":"14, 14"}},{"t":"usc","label":"11 U.S.C. § 524","url":"https://www.law.cornell.edu/uscode/text/11/524","subs":["(a)(1)","(a)(2)"],"stext":{"head":"§524. Effect of discharge","paras":[[0,"(a) A discharge in a case under this title—"],[1,"(1) voids any judgment at any time obtained, to the extent that such judgment is a determination of the personal liability of the debtor with respect to any debt discharged under section 727, 944, 1141, 1192, 1228, or 1328 of this title, whether or not discharge of such debt is waived;"],[1,"(2) operates as an injunction against the commencement or continuation of an action, the employment of process, or an act, to collect, recover or offset any such debt as a personal liability of the debtor, whether or not discharge of such debt is waived; and"],[1,"(3) operates as an injunction against the commencement or continuation of an action, the employment of process, or an act, to collect or recover from, or offset against, property of the debtor of the kind specified in section 541(a)(2) of this title that is acquired after the commencement of the case, on account of any allowable community claim, except a community claim that is excepted from discharge under section 523, 1192, 1228(a)(1), or 1328(a)(1), or that would be so excepted, determined in accordance with the provisions of sections 523(c) and 523(d) of this title, in a case concerning the debtor's spouse commenced on the date of the filing of the petition in the case concerning the debtor, whether or not discharge of the debt based on such community claim is waived."],[0,"(b) Subsection (a)(3) of this section does not apply if—"],[1,"(1)(A) the debtor's spouse is a debtor in a case under this title, or a bankrupt or a debtor in a case under the Bankruptcy Act, commenced within six years of the date of the filing of the petition in the case concerning the debtor; and"],[1,"(B) the court does not grant the debtor's spouse a discharge in such case concerning the debtor's spouse; or"],[1,"(2)(A) the court would not grant the debtor's spouse a discharge in a case under chapter 7 of this title concerning such spouse commenced on the date of the filing of the petition in the case concerning the debtor; and"],[1,"(B) a determination that the court would not so grant such discharge is made by the bankruptcy court within the time and in the manner provided for a determination under section 727 of this title of whether a debtor is granted a discharge."],[0,"(c) An agreement between a holder of a claim and the debtor, the consideration for which, in whole or in part, is based on a debt that is dischargeable in a case under this title is enforceable only to any extent enforceable under applicable nonbankruptcy law, whether or not discharge of such debt is waived, only if—"],[1,"(1) such agreement was made before the granting of the discharge under section 727, 1141, 1192, 1228, or 1328 of this title;"],[1,"(2) the debtor received the disclosures described in subsection (k) at or before the time at which the debtor signed the agreement;"],[1,"(3) such agreement has been filed with the court and, if applicable, accompanied by a declaration or an affidavit of the attorney that represented the debtor during the course of negotiating an agreement under this subsection, which states that—"],[2,"(A) such agreement represents a fully informed and voluntary agreement by the debtor;"],[2,"(B) such agreement does not impose an undue hardship on the debtor or a dependent of the debtor; and"],[2,"(C) the attorney fully advised the debtor of the legal effect and consequences of—"],[3,"(i) an agreement of the kind specified in this subsection; and"],[3,"(ii) any default under such an agreement;"],[1,"(4) the debtor has not rescinded such agreement at any time prior to discharge or within sixty days after such agreement is filed with the court, whichever occurs later, by giving notice of rescission to the holder of such claim;"],[1,"(5) the provisions of subsection (d) of this section have been complied with; and"],[1,"(6)(A) in a case concerning an individual who was not represented by an attorney during the course of negotiating an agreement under this subsection, the court approves such agreement as—"],[2,"(i) not imposing an undue hardship on the debtor or a dependent of the debtor; and"],[2,"(ii) in the best interest of the debtor."],[1,"(B) Subparagraph (A) shall not apply to the extent that such debt is a consumer debt secured by real property."],[0,"(d) In a case concerning an individual, when the court has determined whether to grant or not to grant a discharge under section 727, 1141, 1192, 1228, or 1328 of this title, the court may hold a hearing at which the debtor shall appear in person. At any such hearing, the court shall inform the debtor that a discharge has been granted or the reason why a discharge has not been granted. If a discharge has been granted and if the debtor desires to make an agreement of the kind specified in subsection (c) of this section and was not represented by an attorney during the course of negotiating such agreement, then the court shall hold a hearing at which the debtor shall appear in person and at such hearing the court shall—"],[1,"(1) inform the debtor—"],[2,"(A) that such an agreement is not required under this title, under nonbankruptcy law, or under any agreement not made in accordance with the provisions of subsection (c) of this section; and"],[2,"(B) of the legal effect and consequences of—"],[3,"(i) an agreement of the kind specified in subsection (c) of this section; and"],[3,"(ii) a default under such an agreement; and"],[1,"(2) determine whether the agreement that the debtor desires to make complies with the requirements of subsection (c)(6) of this section, if the consideration for such agreement is based in whole or in part on a consumer debt that is not secured by real property of the debtor."],[0,"(e) Except as provided in subsection (a)(3) of this section, discharge of a debt of the debtor does not affect the liability of any other entity on, or the property of any other entity for, such debt."],[0,"(f) Nothing contained in subsection (c) or (d) of this section prevents a debtor from voluntarily repaying any debt."],[0,"(g)(1)(A) After notice and hearing, a court that enters an order confirming a plan of reorganization under chapter 11 may issue, in connection with such order, an injunction in accordance with this subsection to supplement the injunctive effect of a discharge under this section."],[0,"(B) An injunction may be issued under subparagraph (A) to enjoin entities from taking legal action for the purpose of directly or indirectly collecting, recovering, or receiving payment or recovery with respect to any claim or demand that, under a plan of reorganization, is to be paid in whole or in part by a trust described in paragraph (2)(B)(i), except such legal actions as are expressly allowed by the injunction, the confirmation order, or the plan of reorganization."],[0,"(2)(A) Subject to subsection (h), if the requirements of subparagraph (B) are met at the time an injunction described in paragraph (1) is entered, then after entry of such injunction, any proceeding that involves the validity, application, construction, or modification of such injunction, or of this subsection with respect to such injunction, may be commenced only in the district court in which such injunction was entered, and such court shall have exclusive jurisdiction over any such proceeding without regard to the amount in controversy."],[0,"(B) The requirements of this subparagraph are that—"],[1,"(i) the injunction is to be implemented in connection with a trust that, pursuant to the plan of reorganization—"],[2,"(I) is to assume the liabilities of a debtor which at the time of entry of the order for relief has been named as a defendant in personal injury, wrongful death, or property-damage actions seeking recovery for damages allegedly caused by the presence of, or exposure to, asbestos or asbestos-containing products;"],[2,"(II) is to be funded in whole or in part by the securities of 1 or more debtors involved in such plan and by the obligation of such debtor or debtors to make future payments, including dividends;"],[2,"(III) is to own, or by the exercise of rights granted under such plan would be entitled to own if specified contingencies occur, a majority of the voting shares of—"],[3,"(aa) each such debtor;"],[3,"(bb) the parent corporation of each such debtor; or"],[3,"(cc) a subsidiary of each such debtor that is also a debtor; and"],[2,"(IV) is to use its assets or income to pay claims and demands; and"],[1,"(ii) subject to subsection (h), the court determines that—"],[2,"(I) the debtor is likely to be subject to substantial future demands for payment arising out of the same or similar conduct or events that gave rise to the claims that are addressed by the injunction;"],[2,"(II) the actual amounts, numbers, and timing of such future demands cannot be determined;"],[2,"(III) pursuit of such demands outside the procedures prescribed by such plan is likely to threaten the plan's purpose to deal equitably with claims and future demands;"],[2,"(IV) as part of the process of seeking confirmation of such plan—"],[3,"(aa) the terms of the injunction proposed to be issued under paragraph (1)(A), including any provisions barring actions against third parties pursuant to paragraph (4)(A), are set out in such plan and in any disclosure statement supporting the plan; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/524?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§524. Effect of discharge","tname":"Bankruptcy","by":{"0":"passim, 23, passim","1":"4, 5, 13, 14, passim","2":"3, 28, 34","3":"10, 11, 14, 16"}},{"t":"usc","label":"11 U.S.C. § 727","url":"https://www.law.cornell.edu/uscode/text/11/727","subs":["(b)"],"stext":{"head":"§727. Discharge","paras":[[0,"(a) The court shall grant the debtor a discharge, unless—"],[1,"(1) the debtor is not an individual;"],[1,"(2) the debtor, with intent to hinder, delay, or defraud a creditor or an officer of the estate charged with custody of property under this title, has transferred, removed, destroyed, mutilated, or concealed, or has permitted to be transferred, removed, destroyed, mutilated, or concealed—"],[2,"(A) property of the debtor, within one year before the date of the filing of the petition; or"],[2,"(B) property of the estate, after the date of the filing of the petition;"],[1,"(3) the debtor has concealed, destroyed, mutilated, falsified, or failed to keep or preserve any recorded information, including books, documents, records, and papers, from which the debtor's financial condition or business transactions might be ascertained, unless such act or failure to act was justified under all of the circumstances of the case;"],[1,"(4) the debtor knowingly and fraudulently, in or in connection with the case—"],[2,"(A) made a false oath or account;"],[2,"(B) presented or used a false claim;"],[2,"(C) gave, offered, received, or attempted to obtain money, property, or advantage, or a promise of money, property, or advantage, for acting or forbearing to act; or"],[2,"(D) withheld from an officer of the estate entitled to possession under this title, any recorded information, including books, documents, records, and papers, relating to the debtor's property or financial affairs;"],[1,"(5) the debtor has failed to explain satisfactorily, before determination of denial of discharge under this paragraph, any loss of assets or deficiency of assets to meet the debtor's liabilities;"],[1,"(6) the debtor has refused, in the case—"],[2,"(A) to obey any lawful order of the court, other than an order to respond to a material question or to testify;"],[2,"(B) on the ground of privilege against self-incrimination, to respond to a material question approved by the court or to testify, after the debtor has been granted immunity with respect to the matter concerning which such privilege was invoked; or"],[2,"(C) on a ground other than the properly invoked privilege against self-incrimination, to respond to a material question approved by the court or to testify;"],[1,"(7) the debtor has committed any act specified in paragraph (2), (3), (4), (5), or (6) of this subsection, on or within one year before the date of the filing of the petition, or during the case, in connection with another case, under this title or under the Bankruptcy Act, concerning an insider;"],[1,"(8) the debtor has been granted a discharge under this section, under section 1141 of this title, or under section 14, 371, or 476 of the Bankruptcy Act, in a case commenced within 8 years before the date of the filing of the petition;"],[1,"(9) the debtor has been granted a discharge under section 1228 or 1328 of this title, or under section 660 or 661 of the Bankruptcy Act, in a case commenced within six years before the date of the filing of the petition, unless payments under the plan in such case totaled at least—"],[2,"(A) 100 percent of the allowed unsecured claims in such case; or"],[2,"(B)(i) 70 percent of such claims; and"],[2,"(ii) the plan was proposed by the debtor in good faith, and was the debtor's best effort;"],[1,"(10) the court approves a written waiver of discharge executed by the debtor after the order for relief under this chapter;"],[1,"(11) after filing the petition, the debtor failed to complete an instructional course concerning personal financial management described in section 111, except that this paragraph shall not apply with respect to a debtor who is a person described in section 109(h)(4) or who resides in a district for which the United States trustee (or the bankruptcy administrator, if any) determines that the approved instructional courses are not adequate to service the additional individuals who would otherwise be required to complete such instructional courses under this section (The United States trustee (or the bankruptcy administrator, if any) who makes a determination described in this paragraph shall review such determination not later than 1 year after the date of such determination, and not less frequently than annually thereafter.); or"],[1,"(12) the court after notice and a hearing held not more than 10 days before the date of the entry of the order granting the discharge finds that there is reasonable cause to believe that—"],[2,"(A) section 522(q)(1) may be applicable to the debtor; and"],[2,"(B) there is pending any proceeding in which the debtor may be found guilty of a felony of the kind described in section 522(q)(1)(A) or liable for a debt of the kind described in section 522(q)(1)(B)."],[0,"(b) Except as provided in section 523 of this title, a discharge under subsection (a) of this section discharges the debtor from all debts that arose before the date of the order for relief under this chapter, and any liability on a claim that is determined under section 502 of this title as if such claim had arisen before the commencement of the case, whether or not a proof of claim based on any such debt or liability is filed under section 501 of this title, and whether or not a claim based on any such debt or liability is allowed under section 502 of this title."],[0,"(c)(1) The trustee, a creditor, or the United States trustee may object to the granting of a discharge under subsection (a) of this section."],[0,"(2) On request of a party in interest, the court may order the trustee to examine the acts and conduct of the debtor to determine whether a ground exists for denial of discharge."],[0,"(d) On request of the trustee, a creditor, or the United States trustee, and after notice and a hearing, the court shall revoke a discharge granted under subsection (a) of this section if—"],[1,"(1) such discharge was obtained through the fraud of the debtor, and the requesting party did not know of such fraud until after the granting of such discharge;"],[1,"(2) the debtor acquired property that is property of the estate, or became entitled to acquire property that would be property of the estate, and knowingly and fraudulently failed to report the acquisition of or entitlement to such property, or to deliver or surrender such property to the trustee;"],[1,"(3) the debtor committed an act specified in subsection (a)(6) of this section; or"],[1,"(4) the debtor has failed to explain satisfactorily—"],[2,"(A) a material misstatement in an audit referred to in section 586(f) of title 28; or"],[2,"(B) a failure to make available for inspection all necessary accounts, papers, documents, financial records, files, and all other papers, things, or property belonging to the debtor that are requested for an audit referred to in section 586(f) of title 28."],[0,"(e) The trustee, a creditor, or the United States trustee may request a revocation of a discharge—"],[1,"(1) under subsection (d)(1) of this section within one year after such discharge is granted; or"],[1,"(2) under subsection (d)(2) or (d)(3) of this section before the later of—"],[2,"(A) one year after the granting of such discharge; and"],[2,"(B) the date the case is closed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/727?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§727. Discharge","tname":"Bankruptcy","by":{"0":"4","1":"2, 30, 30","2":"3, 47"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"2"}},{"t":"law","label":"Pub. L. No. 109-8","url":"https://www.govinfo.gov/link/plaw/109/public/8","by":{"0":"25"}},{"t":"case","label":"Abbott Labs. v. Unlimited Beverages, Inc.","cite":"218 F.3d 1238","y":2000,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/218/1238/","by":{"1":"20"}},{"t":"case","label":"Alyeska Pipeline Serv. Co. v. Wilderness Soc’y","cite":"421 U.S. 240","y":1975,"id":"1974/73-1977","sc":1,"ar":1,"sum":"Under the \"American Rule\" that attorneys' fees are not ordinarily recoverable by the prevailing litigant in federal litigation in the absence of statutory authorization, respondents, which had instituted litigation to prevent issuance of Government permits required for construction of the trans-Alaska oil pipeline, cannot recover attorneys' fees from petitioner based on the \"private attorney general\" approach …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Axia NetMedia Corp. v. Massachusetts Tech. Park Corp.","cite":"889 F.3d 1","y":2018,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/889/1/","by":{"1":"17","2":"22"}},{"t":"case","label":"(III) Cases—Continued: CFE Racing Prods., Inc. v. BMF Wheels, Inc.","cite":"793 F.3d 571","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/793/571/","by":{"1":"17, 22","2":"34"}},{"t":"case","label":"California Artificial Stone Paving Co. v. Molitor","cite":"113 U.S. 609","y":1885,"id":"scdb/1884-153","sc":1,"op":1,"ar":6,"sum":"A certificate of division of opinion under § 652 Rev. Stat., can be resorted to only when “ a question ” has occurred on which the judges have differed, and where “ the point ” of disagreement may be distinctly stated.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"passim","2":"passim","3":"9"}},{"t":"case","label":"Chambers v. Nasco, Inc.","cite":"501 U.S. 32","y":1991,"id":"1990/90-256","sc":1,"op":1,"ar":1,"sum":"The District Court properly invoked its inherent power in assessing as a sanction for Chambers' bad-faith conduct the attorney's fees and related expenses paid by NASCO.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4, 26","2":"4, 26, 36"}},{"t":"case","label":"Chao v. Gotham Registry, Inc.","cite":"514 F.3d 280","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/514/280/","by":{"1":"20","2":"22, 26"}},{"t":"case","label":"City of New York v. Mickalis Pawn Shop, LLC","cite":"645 F.3d 114","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/645/114/","by":{"1":"17"}},{"t":"case","label":"Cox v. Zale Del., Inc.","cite":"239 F.3d 910","y":2001,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/239/910/","by":{"1":"14"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"1":"12, 31"}},{"t":"case","label":"First State Bank of Roscoe v. Stabler","cite":"914 F.3d 1129","y":2019,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/914/1129/","ar":7,"sum":"Recognizing bankruptcy court’s contempt authority.","sumSrc":"brief:2","by":{"1":"22","2":"4, 17, 45"}},{"t":"case","label":"Gascho v. Global Fitness Holdings, LLC","cite":"875 F.3d 795","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/875/795/","by":{"1":"17","2":"20, 22"}},{"t":"case","label":"Gompers v. Bucks Stove & Range Co.","cite":"221 U.S. 418","y":1911,"id":"1900-1940/221us418","sc":1,"sum":"The Court refused to reexamine the validity of the injunction issued by the lower court. However, the convictions were reversed on the ground that the contempts were civil but the lower court had treated them as criminal in nature. The aim of civil contempt is remediation while the purpose of crminal contempt is punitive.","sumSrc":"Oyez","by":{"1":"22, 31","2":"27, 43"}},{"t":"case","label":"Hutto v. Finney","cite":"437 U.S. 678","y":1978,"id":"1977/76-1660","sc":1,"sum":"The Court held that punitive isolation for longer than thirty days in Arkansas prisons constituted cruel and unusual punishment and violated the Constitution. Justice Stevens conceded that isolation in and of itself was not necessarily unconstitutional and may in fact serve an important, legitimate interest in administering a prison.","sumSrc":"Oyez","by":{"1":"28","2":"26, 36, 40"}},{"t":"case","label":"International Longshoremen’s Ass’n v. Philadelphia Marine Trade Ass’n","cite":"389 U.S. 64","y":1967,"id":"1967/34","sc":1,"op":1,"sum":"Since the District Court's decree, which was an \"order granting an injunction\" within the meaning of Fed. Rule Civ. Proc. 65 (d), did not Local 1291, et al. v. Philadelphia Marine Trade Association, also on certiorari to the same court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15","2":"passim","3":"11"}},{"t":"case","label":"Katchen v. Landy","cite":"382 U.S. 323","y":1966,"id":"1965/28","sc":1,"op":1,"sum":"A bankruptcy court has summary jurisdiction to order the surrender of voidable preferences asserted and proved by the trustee in response to a claim filed by the creditor who received the preferences.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4, 27","2":"44"}},{"t":"case","label":"Latino Officers Ass’n City of N.Y., Inc. v. City of New York","cite":"558 F.3d 159","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/558/159/","by":{"1":"16","2":"35"}},{"t":"case","label":"Michaelson v. United States ex rel. Chicago, St. Paul, Minneapolis & Omaha Ry. Co.","cite":"266 U.S. 42","y":1924,"id":"scdb/1924-055","sc":1,"sum":"1. The Clayton Act, October 15, 1914, §§ 21, 22, c. 323, 38 Stat. 738, provides that any person who shall wilfully disobey any writ, etc., of any District Court of the United States or court of the District of Columbia, by doing any act or thing therein or thereby forbidden, if of such character as to constitute also a criminal offense under any statute of the United States or law of the State in which committed, …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"Northeast Women’s Ctr., Inc. v. McMonagle","cite":"939 F.2d 57","y":1991,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/939/57/","by":{"1":"20"}},{"t":"case","label":"Pertuso v. Ford Motor Credit Co.","cite":"233 F.3d 417","y":2000,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/233/417/","sum":"Explaining that “[t]he obvious purpose” of Section 524 “is to enjoin the proscribed conduct,” and that “the traditional remedy for violation of an injunction lies in contempt proceedings”.","sumSrc":"brief:1","by":{"1":"14"}},{"t":"case","label":"Robin Woods Inc. v. Woods","cite":"28 F.3d 396","y":1994,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/28/396/","by":{"1":"22, 23","3":"7"}},{"t":"case","label":"Schmidt v. Lessard","cite":"414 U.S. 473","y":1974,"id":"1973/73-568","sc":1,"op":1,"sum":"Noting that civil contempt usually is not appropriate unless “those who must obey” an order “will know what the court intends to require and what it means to forbid”.","sumSrc":"opinion","by":{"1":"10","2":"21, 22","3":"10"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Sherwood Park Bus. Ctr., LLC v. Taggart","cite":"341 P.3d 96","y":2014,"court":"Or. App.","url":"https://www.courtlistener.com/c/P.3d/341/96/","op":17,"by":{"1":"7"}},{"t":"case","label":"Shillitani v. United States","cite":"384 U.S. 364","y":1966,"id":"1965/412","sc":1,"sum":"Petitioners, having refused to testify before a grand jury under immunity granted by the respective District Courts under the Narcotic Control Act of 1956, were found guilty of contempt in proceedings' under Fed. Rule Crim. Proc. 42 (b). Each was sentenced to two years' imprisonment, with the proviso that he would be released sooner if and when he answered the questions. The Court of Appeals, construing the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22, 31","2":"20, 43"}},{"t":"case","label":"Swift & Co. v. United States","cite":"196 U.S. 375","y":1905,"id":"1900-1940/196us375","sc":1,"sum":"The Court held that congressional power under the Commerce Clause justified regulations of the “beef trust.”","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Tennessee Student Assistance Corp. v. Hood","cite":"541 U.S. 440","y":2004,"id":"2003/02-1606","sc":1,"sum":"Instead, the Court ruled that discharging a debt owed to a state in a bankruptcy procedure is different from a suit and therefore not barred by sovereign immunity. \"A bankruptcy court is able to provide the debtor a fresh start in this manner ... because the court's jurisdiction is premised on the debtor and his estate, and not on the creditors,\" wrote the Court.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"TiVo Inc. v. EchoStar Corp.","cite":"646 F.3d 869","y":2011,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/646/869/","ar":1,"by":{"1":"16","2":"22","3":"12"}},{"t":"case","label":"United States v. Saccoccia","cite":"433 F.3d 19","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/433/19/","by":{"1":"16, 17","2":"34"}},{"t":"case","label":"United States v. Stitt","cite":"139 S. Ct. 399","y":2018,"id":"2018/17-765","sc":1,"sum":"The term “burglary” in the Armed Career Criminal Act includes burglary of a structure or vehicle that has been adapted or is customarily used for overnight accommodation.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"31"}},{"t":"case","label":"United Student Aid Funds, Inc. v. Espinosa","cite":"559 U.S. 260","y":2010,"id":"2009/08-1134","sc":1,"sum":"The Court held that Chapter 13 bankruptcy plans which discharge student loans are not void if the debtor fails to provide evidence of \"undue hardship\" in an adversary proceeding.","sumSrc":"Oyez","by":{"1":"3","2":"28, 46"}},{"t":"case","label":"Young v. United States ex rel. Vuitton et Fils S. A.","cite":"481 U.S. 787","y":1987,"id":"1986/85-1329","sc":1,"op":1,"sum":"The judgment is reversed. 780 F. 2d 179, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13","2":"19"}},{"t":"usc","label":"11 U.S.C. § 106","url":"https://www.law.cornell.edu/uscode/text/11/106","subs":["(a)(1)"],"by":{"1":"4"}},{"t":"usc","label":"11 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/11/301","stext":{"head":"§301. Voluntary cases","paras":[[0,"(a) A voluntary case under a chapter of this title is commenced by the filing with the bankruptcy court of a petition under such chapter by an entity that may be a debtor under such chapter."],[0,"(b) The commencement of a voluntary case under a chapter of this title constitutes an order for relief under such chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/301?type=usc&year=mostrecent&link-type=html"},"head":"§301. Voluntary cases","tname":"Bankruptcy","by":{"1":"1","2":"3"}},{"t":"usc","label":"11 U.S.C. § 307","url":"https://www.law.cornell.edu/uscode/text/11/307","by":{"1":"1"}},{"t":"usc","label":"11 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/11/501","stext":{"head":"§501. Filing of proofs of claims or interests","paras":[[0,"(a) A creditor or an indenture trustee may file a proof of claim. An equity security holder may file a proof of interest."],[0,"(b) If a creditor does not timely file a proof of such creditor's claim, an entity that is liable to such creditor with the debtor, or that has secured such creditor, may file a proof of such claim."],[0,"(c) If a creditor does not timely file a proof of such creditor's claim, the debtor or the trustee may file a proof of such claim."],[0,"(d) A claim of a kind specified in section 502(e)(2), 502(f), 502(g), 502(h) or 502(i) of this title may be filed under subsection (a), (b), or (c) of this section the same as if such claim were a claim against the debtor and had arisen before the date of the filing of the petition."],[0,"(e) A claim arising from the liability of a debtor for fuel use tax assessed consistent with the requirements of section 31705 of title 49 may be filed by the base jurisdiction designated pursuant to the International Fuel Tax Agreement (as defined in section 31701 of title 49) and, if so filed, shall be allowed as a single claim."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/501?type=usc&year=mostrecent&link-type=html"},"head":"§501. Filing of proofs of claims or interests","tname":"Bankruptcy","by":{"1":"2, 19","2":"30"}},{"t":"usc","label":"11 U.S.C. § 523","url":"https://www.law.cornell.edu/uscode/text/11/523","subs":["(a)","(a)(1)","(a)(1)(C)","(a)(2)","(a)(4)","(a)(6)","(a)(7)","(a)(8)","(a)(11)","(a)(12)","(a)(13)","(a)(14B)","(a)(18)","(c)(1)","(d)"],"stext":{"head":"§523. Exceptions to discharge","paras":[[0,"(a) A discharge under section 727, 1141, 1192 1 1228(a), 1228(b), or 1328(b) of this title does not discharge an individual debtor from any debt—"],[1,"(1) for a tax or a customs duty—"],[2,"(A) of the kind and for the periods specified in section 507(a)(3) or 507(a)(8) of this title, whether or not a claim for such tax was filed or allowed;"],[2,"(B) with respect to which a return, or equivalent report or notice, if required—"],[3,"(i) was not filed or given; or"],[3,"(ii) was filed or given after the date on which such return, report, or notice was last due, under applicable law or under any extension, and after two years before the date of the filing of the petition; or"],[2,"(C) with respect to which the debtor made a fraudulent return or willfully attempted in any manner to evade or defeat such tax;"],[1,"(2) for money, property, services, or an extension, renewal, or refinancing of credit, to the extent obtained by—"],[2,"(A) false pretenses, a false representation, or actual fraud, other than a statement respecting the debtor's or an insider's financial condition;"],[2,"(B) use of a statement in writing—"],[3,"(i) that is materially false;"],[3,"(ii) respecting the debtor's or an insider's financial condition;"],[3,"(iii) on which the creditor to whom the debtor is liable for such money, property, services, or credit reasonably relied; and"],[3,"(iv) that the debtor caused to be made or published with intent to deceive; or"],[2,"(C)(i) for purposes of subparagraph (A)—"],[3,"(I) consumer debts owed to a single creditor and aggregating more than $500 2 for luxury goods or services incurred by an individual debtor on or within 90 days before the order for relief under this title are presumed to be nondischargeable; and"],[3,"(II) cash advances aggregating more than $750 2 that are extensions of consumer credit under an open end credit plan obtained by an individual debtor on or within 70 days before the order for relief under this title, are presumed to be nondischargeable; and"],[2,"(ii) for purposes of this subparagraph—"],[3,"(I) the terms \"consumer\", \"credit\", and \"open end credit plan\" have the same meanings as in section 103 of the Truth in Lending Act; and"],[3,"(II) the term \"luxury goods or services\" does not include goods or services reasonably necessary for the support or maintenance of the debtor or a dependent of the debtor;"],[1,"(3) neither listed nor scheduled under section 521(a)(1) of this title, with the name, if known to the debtor, of the creditor to whom such debt is owed, in time to permit—"],[2,"(A) if such debt is not of a kind specified in paragraph (2), (4), or (6) of this subsection, timely filing of a proof of claim, unless such creditor had notice or actual knowledge of the case in time for such timely filing; or"],[2,"(B) if such debt is of a kind specified in paragraph (2), (4), or (6) of this subsection, timely filing of a proof of claim and timely request for a determination of dischargeability of such debt under one of such paragraphs, unless such creditor had notice or actual knowledge of the case in time for such timely filing and request;"],[1,"(4) for fraud or defalcation while acting in a fiduciary capacity, embezzlement, or larceny;"],[1,"(5) for a domestic support obligation;"],[1,"(6) for willful and malicious injury by the debtor to another entity or to the property of another entity;"],[1,"(7) to the extent such debt is for a fine, penalty, or forfeiture payable to and for the benefit of a governmental unit, and is not compensation for actual pecuniary loss, other than a tax penalty—"],[2,"(A) relating to a tax of a kind not specified in paragraph (1) of this subsection; or"],[2,"(B) imposed with respect to a transaction or event that occurred before three years before the date of the filing of the petition;"],[1,"(8) unless excepting such debt from discharge under this paragraph would impose an undue hardship on the debtor and the debtor's dependents, for—"],[2,"(A)(i) an educational benefit overpayment or loan made, insured, or guaranteed by a governmental unit, or made under any program funded in whole or in part by a governmental unit or nonprofit institution; or"],[2,"(ii) an obligation to repay funds received as an educational benefit, scholarship, or stipend; or"],[2,"(B) any other educational loan that is a qualified education loan, as defined in section 221(d)(1) of the Internal Revenue Code of 1986, incurred by a debtor who is an individual;"],[1,"(9) for death or personal injury caused by the debtor's operation of a motor vehicle, vessel, or aircraft if such operation was unlawful because the debtor was intoxicated from using alcohol, a drug, or another substance;"],[1,"(10) that was or could have been listed or scheduled by the debtor in a prior case concerning the debtor under this title or under the Bankruptcy Act in which the debtor waived discharge, or was denied a discharge under section 727(a)(2), (3), (4), (5), (6), or (7) of this title, or under section 14c(1), (2), (3), (4), (6), or (7) of such Act;"],[1,"(11) provided in any final judgment, unreviewable order, or consent order or decree entered in any court of the United States or of any State, issued by a Federal depository institutions regulatory agency, or contained in any settlement agreement entered into by the debtor, arising from any act of fraud or defalcation while acting in a fiduciary capacity committed with respect to any depository institution or insured credit union;"],[1,"(12) for malicious or reckless failure to fulfill any commitment by the debtor to a Federal depository institutions regulatory agency to maintain the capital of an insured depository institution, except that this paragraph shall not extend any such commitment which would otherwise be terminated due to any act of such agency;"],[1,"(13) for any payment of an order of restitution issued under title 18, United States Code;"],[1,"(14) incurred to pay a tax to the United States that would be nondischargeable pursuant to paragraph (1);"],[1,"(14A) incurred to pay a tax to a governmental unit, other than the United States, that would be nondischargeable under paragraph (1);"],[1,"(14B) incurred to pay fines or penalties imposed under Federal election law;"],[1,"(15) to a spouse, former spouse, or child of the debtor and not of the kind described in paragraph (5) that is incurred by the debtor in the course of a divorce or separation or in connection with a separation agreement, divorce decree or other order of a court of record, or a determination made in accordance with State or territorial law by a governmental unit;"],[1,"(16) for a fee or assessment that becomes due and payable after the order for relief to a membership association with respect to the debtor's interest in a unit that has condominium ownership, in a share of a cooperative corporation, or a lot in a homeowners association, for as long as the debtor or the trustee has a legal, equitable, or possessory ownership interest in such unit, such corporation, or such lot, but nothing in this paragraph shall except from discharge the debt of a debtor for a membership association fee or assessment for a period arising before entry of the order for relief in a pending or subsequent bankruptcy case;"],[1,"(17) for a fee imposed on a prisoner by any court for the filing of a case, motion, complaint, or appeal, or for other costs and expenses assessed with respect to such filing, regardless of an assertion of poverty by the debtor under subsection (b) or (f)(2) of section 1915 of title 28 (or a similar non-Federal law), or the debtor's status as a prisoner, as defined in section 1915(h) of title 28 (or a similar non-Federal law);"],[1,"(18) owed to a pension, profit-sharing, stock bonus, or other plan established under section 401, 403, 408, 408A, 414, 457, or 501(c) of the Internal Revenue Code of 1986, under—"],[2,"(A) a loan permitted under section 408(b)(1) of the Employee Retirement Income Security Act of 1974, or subject to section 72(p) of the Internal Revenue Code of 1986; or"],[2,"(B) a loan from a thrift savings plan permitted under subchapter III of chapter 84 of title 5, that satisfies the requirements of section 8433(g) of such title;"],[1,"but nothing in this paragraph may be construed to provide that any loan made under a governmental plan under section 414(d), or a contract or account under section 403(b), of the Internal Revenue Code of 1986 constitutes a claim or a debt under this title;"],[1,"(19) that—"],[2,"(A) is for—"],[3,"(i) the violation of any of the Federal securities laws (as that term is defined in section 3(a)(47) of the Securities Exchange Act of 1934), any of the State securities laws, or any regulation or order issued under such Federal or State securities laws; or"],[3,"(ii) common law fraud, deceit, or manipulation in connection with the purchase or sale of any security; and"],[2,"(B) results, before, on, or after the date on which the petition was filed, from—"],[3,"(i) any judgment, order, consent order, or decree entered in any Federal or State judicial or administrative proceeding;"],[3,"(ii) any settlement agreement entered into by the debtor; or"],[3,"(iii) any court or administrative order for any damages, fine, penalty, citation, restitutionary payment, disgorgement payment, attorney fee, cost, or other payment owed by the debtor; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/523?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":2,"sum":"Noting only three categories of debts for which creditors must obtain advance determinations.","sumSrc":"opinion","head":"§523. Exceptions to discharge","tname":"Bankruptcy","by":{"1":"2, 19, 2, 2, 2, 3, 19, 26, 3, 19, 26, 3, 19, 26, 2, 2, 27, 2, 2, 2, 2, 2, 2, 19, 28","2":"3, 27, 46, 46, 46, 3, 27, 44, 45","3":"10, 11, 14, 14"}},{"t":"usc","label":"11 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/11/701","stext":{"head":"§701. Interim trustee","paras":[[0,"(a)(1) Promptly after the order for relief under this chapter, the United States trustee shall appoint one disinterested person that is a member of the panel of private trustees established under section 586(a)(1) of title 28 or that is serving as trustee in the case immediately before the order for relief under this chapter to serve as interim trustee in the case."],[0,"(2) If none of the members of such panel is willing to serve as interim trustee in the case, then the United States trustee may serve as interim trustee in the case."],[0,"(b) The service of an interim trustee under this section terminates when a trustee elected or designated under section 702 of this title to serve as trustee in the case qualifies under section 322 of this title."],[0,"(c) An interim trustee serving under this section is a trustee in a case under this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/701?type=usc&year=mostrecent&link-type=html"},"head":"§701. Interim trustee","tname":"Bankruptcy","by":{"1":"2, 3, 6, 30","2":"43"}},{"t":"usc","label":"11 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/11/1101","stext":{"head":"§1101. Definitions for this chapter","paras":[[0,"In this chapter—"],[1,"(1) \"debtor in possession\" means debtor except when a person that has qualified under section 322 of this title is serving as trustee in the case;"],[1,"(2) \"substantial consummation\" means—"],[2,"(A) transfer of all or substantially all of the property proposed by the plan to be transferred;"],[2,"(B) assumption by the debtor or by the successor to the debtor under the plan of the business or of the management of all or substantially all of the property dealt with by the plan; and"],[2,"(C) commencement of distribution under the plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1101?type=usc&year=mostrecent&link-type=html"},"head":"§1101. Definitions for this chapter","tname":"Bankruptcy","by":{"1":"2","2":"30"}},{"t":"usc","label":"11 U.S.C. § 1141","url":"https://www.law.cornell.edu/uscode/text/11/1141","stext":{"head":"§1141. Effect of confirmation","paras":[[0,"(a) Except as provided in subsections (d)(2) and (d)(3) of this section, the provisions of a confirmed plan bind the debtor, any entity issuing securities under the plan, any entity acquiring property under the plan, and any creditor, equity security holder, or general partner in the debtor, whether or not the claim or interest of such creditor, equity security holder, or general partner is impaired under the plan and whether or not such creditor, equity security holder, or general partner has accepted the plan."],[0,"(b) Except as otherwise provided in the plan or the order confirming the plan, the confirmation of a plan vests all of the property of the estate in the debtor."],[0,"(c) Except as provided in subsections (d)(2) and (d)(3) of this section and except as otherwise provided in the plan or in the order confirming the plan, after confirmation of a plan, the property dealt with by the plan is free and clear of all claims and interests of creditors, equity security holders, and of general partners in the debtor."],[0,"(d)(1) Except as otherwise provided in this subsection, in the plan, or in the order confirming the plan, the confirmation of a plan—"],[1,"(A) discharges the debtor from any debt that arose before the date of such confirmation, and any debt of a kind specified in section 502(g), 502(h), or 502(i) of this title, whether or not—"],[2,"(i) a proof of the claim based on such debt is filed or deemed filed under section 501 of this title;"],[2,"(ii) such claim is allowed under section 502 of this title; or"],[2,"(iii) the holder of such claim has accepted the plan; and"],[1,"(B) terminates all rights and interests of equity security holders and general partners provided for by the plan."],[0,"(2) A discharge under this chapter does not discharge a debtor who is an individual from any debt excepted from discharge under section 523 of this title."],[0,"(3) The confirmation of a plan does not discharge a debtor if—"],[1,"(A) the plan provides for the liquidation of all or substantially all of the property of the estate;"],[1,"(B) the debtor does not engage in business after consummation of the plan; and"],[1,"(C) the debtor would be denied a discharge under section 727(a) of this title if the case were a case under chapter 7 of this title."],[0,"(4) The court may approve a written waiver of discharge executed by the debtor after the order for relief under this chapter."],[0,"(5) In a case in which the debtor is an individual—"],[1,"(A) unless after notice and a hearing the court orders otherwise for cause, confirmation of the plan does not discharge any debt provided for in the plan until the court grants a discharge on completion of all payments under the plan;"],[1,"(B) at any time after the confirmation of the plan, and after notice and a hearing, the court may grant a discharge to the debtor who has not completed payments under the plan if—"],[2,"(i) the value, as of the effective date of the plan, of property actually distributed under the plan on account of each allowed unsecured claim is not less than the amount that would have been paid on such claim if the estate of the debtor had been liquidated under chapter 7 on such date;"],[2,"(ii) modification of the plan under section 1127 is not practicable; and"],[2,"(iii) subparagraph (C) permits the court to grant a discharge; and"],[1,"(C) the court may grant a discharge if, after notice and a hearing held not more than 10 days before the date of the entry of the order granting the discharge, the court finds that there is no reasonable cause to believe that—"],[2,"(i) section 522(q)(1) may be applicable to the debtor; and"],[2,"(ii) there is pending any proceeding in which the debtor may be found guilty of a felony of the kind described in section 522(q)(1)(A) or liable for a debt of the kind described in section 522(q)(1)(B);"],[1,"and if the requirements of subparagraph (A) or (B) are met."],[1,"(6) Notwithstanding paragraph (1), the confirmation of a plan does not discharge a debtor that is a corporation from any debt—"],[2,"(A) of a kind specified in paragraph (2)(A) or (2)(B) of section 523(a) that is owed to a domestic governmental unit, or owed to a person as the result of an action filed under subchapter III of chapter 37 of title 31 or any similar State statute; or"],[2,"(B) for a tax or customs duty with respect to which the debtor—"],[3,"(i) made a fraudulent return; or"],[3,"(ii) willfully attempted in any manner to evade or to defeat such tax or such customs duty."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1141?type=usc&year=mostrecent&link-type=html"},"head":"§1141. Effect of confirmation","tname":"Bankruptcy","by":{"1":"2","2":"3"}},{"t":"usc","label":"11 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/11/1201","stext":{"head":"§1201. Stay of action against codebtor","paras":[[0,"(a) Except as provided in subsections (b) and (c) of this section, after the order for relief under this chapter, a creditor may not act, or commence or continue any civil action, to collect all or any part of a consumer debt of the debtor from any individual that is liable on such debt with the debtor, or that secured such debt, unless—"],[1,"(1) such individual became liable on or secured such debt in the ordinary course of such individual's business; or"],[1,"(2) the case is closed, dismissed, or converted to a case under chapter 7 of this title."],[0,"(b) A creditor may present a negotiable instrument, and may give notice of dishonor of such an instrument."],[0,"(c) On request of a party in interest and after notice and a hearing, the court shall grant relief from the stay provided by subsection (a) of this section with respect to a creditor, to the extent that—"],[1,"(1) as between the debtor and the individual protected under subsection (a) of this section, such individual received the consideration for the claim held by such creditor;"],[1,"(2) the plan filed by the debtor proposes not to pay such claim; or"],[1,"(3) such creditor's interest would be irreparably harmed by continuation of such stay."],[0,"(d) Twenty days after the filing of a request under subsection (c)(2) of this section for relief from the stay provided by subsection (a) of this section, such stay is terminated with respect to the party in interest making such request, unless the debtor or any individual that is liable on such debt with the debtor files and serves upon such party in interest a written objection to the taking of the proposed action."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1201?type=usc&year=mostrecent&link-type=html"},"head":"§1201. Stay of action against codebtor","tname":"Bankruptcy","by":{"1":"2","2":"30"}},{"t":"usc","label":"11 U.S.C. § 1228","url":"https://www.law.cornell.edu/uscode/text/11/1228","stext":{"head":"§1228. Discharge","paras":[[0,"(a) Subject to subsection (d), as soon as practicable after completion by the debtor of all payments under the plan, and in the case of a debtor who is required by a judicial or administrative order, or by statute, to pay a domestic support obligation, after such debtor certifies that all amounts payable under such order or such statute that are due on or before the date of the certification (including amounts due before the petition was filed, but only to the extent provided for by the plan) have been paid, other than payments to holders of allowed claims provided for under section 1222(b)(5) or 1222(b)(9) of this title, unless the court approves a written waiver of discharge executed by the debtor after the order for relief under this chapter, the court shall grant the debtor a discharge of all debts provided for by the plan, allowed under section 503 of this title, or disallowed under section 502 of this title, except any debt—"],[1,"(1) provided for under section 1222(b)(5) or 1222(b)(9) of this title; or"],[1,"(2) of a kind specified in section 523(a) of this title, except as provided in section 1232(c)."],[0,"(b) Subject to subsection (d), at any time after the confirmation of the plan and after notice and a hearing, the court may grant a discharge to a debtor that has not completed payments under the plan only if—"],[1,"(1) the debtor's failure to complete such payments is due to circumstances for which the debtor should not justly be held accountable;"],[1,"(2) the value, as of the effective date of the plan, of property actually distributed under the plan on account of each allowed unsecured claim is not less than the amount that would have been paid on such claim if the estate of the debtor had been liquidated under chapter 7 of this title on such date; and"],[1,"(3) modification of the plan under section 1229 of this title is not practicable."],[0,"(c) A discharge granted under subsection (b) of this section discharges the debtor from all unsecured debts provided for by the plan or disallowed under section 502 of this title, except any debt—"],[1,"(1) provided for under section 1222(b)(5) or 1222(b)(9) of this title; or"],[1,"(2) of a kind specified in section 523(a) of this title, except as provided in section 1232(c)."],[0,"(d) On request of a party in interest before one year after a discharge under this section is granted, and after notice and a hearing, the court may revoke such discharge only if—"],[1,"(1) such discharge was obtained by the debtor through fraud; and"],[1,"(2) the requesting party did not know of such fraud until after such discharge was granted."],[0,"(e) After the debtor is granted a discharge, the court shall terminate the services of any trustee serving in the case."],[0,"(f) The court may not grant a discharge under this chapter unless the court after notice and a hearing held not more than 10 days before the date of the entry of the order granting the discharge finds that there is no reasonable cause to believe that—"],[1,"(1) section 522(q)(1) may be applicable to the debtor; and"],[1,"(2) there is pending any proceeding in which the debtor may be found guilty of a felony of the kind described in section 522(q)(1)(A) or liable for a debt of the kind described in section 522(q)(1)(B)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1228?type=usc&year=mostrecent&link-type=html"},"head":"§1228. Discharge","tname":"Bankruptcy","by":{"1":"2","2":"3"}},{"t":"usc","label":"11 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/11/1301","by":{"1":"2, 20","2":"30"}},{"t":"usc","label":"11 U.S.C. § 1328","url":"https://www.law.cornell.edu/uscode/text/11/1328","subs":["(a)"],"by":{"1":"2","2":"3, 3, 27"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"1":"25"}},{"t":"usc","label":"26 U.S.C. § 7433","url":"https://www.law.cornell.edu/uscode/text/26/7433","subs":["(e)(1)","(d)(3)","(e)","(e)(2)"],"stext":{"head":"§7433. Civil damages for certain unauthorized collection actions","paras":[[0,"(a) In general"],[0,"If, in connection with any collection of Federal tax with respect to a taxpayer, any officer or employee of the Internal Revenue Service recklessly or intentionally, or by reason of negligence, disregards any provision of this title, or any regulation promulgated under this title, such taxpayer may bring a civil action for damages against the United States in a district court of the United States. Except as provided in section 7432, such civil action shall be the exclusive remedy for recovering damages resulting from such actions."],[0,"(b) Damages"],[0,"In any action brought under subsection (a) or petition filed under subsection (e), upon a finding of liability on the part of the defendant, the defendant shall be liable to the plaintiff in an amount equal to the lesser of $1,000,000 ($100,000, in the case of negligence) or the sum of—"],[1,"(1) actual, direct economic damages sustained by the plaintiff as a proximate result of the reckless or intentional or negligent actions of the officer or employee, and"],[1,"(2) the costs of the action."],[0,"(c) Payment authority"],[0,"Claims pursuant to this section shall be payable out of funds appropriated under section 1304 of title 31, United States Code."],[0,"(d) Limitations"],[0,"(1) Requirement that administrative remedies be exhausted"],[1,"A judgment for damages shall not be awarded under subsection (b) unless the court determines that the plaintiff has exhausted the administrative remedies available to such plaintiff within the Internal Revenue Service."],[0,"(2) Mitigation of damages"],[1,"The amount of damages awarded under subsection (b)(1) shall be reduced by the amount of such damages which could have reasonably been mitigated by the plaintiff."],[0,"(3) Period for bringing action"],[1,"Notwithstanding any other provision of law, an action to enforce liability created under this section may be brought without regard to the amount in controversy and may be brought only within 2 years after the date the right of action accrues."],[0,"(e) Actions for violations of certain bankruptcy procedures"],[0,"(1) In general"],[1,"If, in connection with any collection of Federal tax with respect to a taxpayer, any officer or employee of the Internal Revenue Service willfully violates any provision of section 362 (relating to automatic stay) or 524 (relating to effect of discharge) of title 11, United States Code (or any successor provision), or any regulation promulgated under such provision, such taxpayer may petition the bankruptcy court to recover damages against the United States."],[0,"(2) Remedy to be exclusive"],[0,"(A) In general"],[2,"Except as provided in subparagraph (B), notwithstanding section 105 of such title 11, such petition shall be the exclusive remedy for recovering damages resulting from such actions."],[0,"(B) Certain other actions permitted"],[2,"Subparagraph (A) shall not apply to an action under section 362(h) of such title 11 for a violation of a stay provided by section 362 of such title; except that—"],[3,"(i) administrative and litigation costs in connection with such an action may only be awarded under section 7430; and"],[3,"(ii) administrative costs may be awarded only if incurred on or after the date that the bankruptcy petition is filed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/7433?type=usc&year=mostrecent&link-type=html"},"head":"§7433. Civil damages for certain unauthorized collection actions","tname":"Internal Revenue Code","by":{"1":"5","2":"5, 40, 5, 5","3":"14"}},{"t":"usc","label":"28 U.S.C. § 581-589a","url":"https://www.law.cornell.edu/uscode/text/28/581-589a","by":{"1":"1"}},{"t":"usc","label":"28 U.S.C. § 1334","url":"https://www.law.cornell.edu/uscode/text/28/1334","subs":["(b)","(a)","(c)(1)","(c)(2)"],"stext":{"head":"§1334. Bankruptcy cases and proceedings","paras":[[0,"(a) Except as provided in subsection (b) of this section, the district courts shall have original and exclusive jurisdiction of all cases under title 11."],[0,"(b) Except as provided in subsection (e)(2), and notwithstanding any Act of Congress that confers exclusive jurisdiction on a court or courts other than the district courts, the district courts shall have original but not exclusive jurisdiction of all civil proceedings arising under title 11, or arising in or related to cases under title 11."],[0,"(c)(1) Except with respect to a case under chapter 15 of title 11, nothing in this section prevents a district court in the interest of justice, or in the interest of comity with State courts or respect for State law, from abstaining from hearing a particular proceeding arising under title 11 or arising in or related to a case under title 11."],[0,"(2) Upon timely motion of a party in a proceeding based upon a State law claim or State law cause of action, related to a case under title 11 but not arising under title 11 or arising in a case under title 11, with respect to which an action could not have been commenced in a court of the United States absent jurisdiction under this section, the district court shall abstain from hearing such proceeding if an action is commenced, and can be timely adjudicated, in a State forum of appropriate jurisdiction."],[0,"(d) Any decision to abstain or not to abstain made under subsection (c) (other than a decision not to abstain in a proceeding described in subsection (c)(2)) is not reviewable by appeal or otherwise by the court of appeals under section 158(d), 1291, or 1292 of this title or by the Supreme Court of the United States under section 1254 of this title. Subsection (c) and this subsection shall not be construed to limit the applicability of the stay provided for by section 362 of title 11, United States Code, as such section applies to an action affecting the property of the estate in bankruptcy."],[0,"(e) The district court in which a case under title 11 is commenced or is pending shall have exclusive jurisdiction—"],[1,"(1) of all the property, wherever located, of the debtor as of the commencement of such case, and of property of the estate; and"],[1,"(2) over all claims or causes of action that involve construction of section 327 of title 11, United States Code, or rules relating to disclosure requirements under section 327."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1334?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1334. Bankruptcy cases and proceedings","tname":"Judiciary and Judicial Procedure","by":{"1":"3, 27","2":"45, 4, 45, 46, 46"}},{"t":"case","label":"Air & Liquid Sys. Corp. v. Devries","cite":"2019 WL 1245520","y":2019,"court":"Mar. 19","ar":1,"by":{"2":"33, 49"}},{"t":"case","label":"Armstrong v. Executive Office of President","cite":"1 F.3d 1274","y":1993,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/1/1274/","by":{"2":"22"}},{"t":"case","label":"Atlantic Coast Line R.R. v. Brotherhood of Locomotive Eng’rs","cite":"398 U.S. 281","y":1970,"id":"1969/477","sc":1,"sum":"The federal injunction was not justified under the exceptions in § 2283 and thus was improperly issued in this case.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46"}},{"t":"case","label":"Baker Botts L.L.P. v. ASARCO LLC","cite":"135 S. Ct. 2158","y":2015,"id":"2014/14-103","sc":1,"ar":1,"sum":"The Court held that the Bankruptcy Code does not provide an explicit statutory exception to the American rule of attorney fees—that each litigant pays for his own attorney’s fees.","sumSrc":"Oyez","by":{"2":"43, 45"}},{"t":"case","label":"Balla v. Idaho State Bd. of Corr.","cite":"869 F.2d 461","y":1989,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/869/461/","by":{"2":"21"}},{"t":"case","label":"Eden v. Robert A. Chapski, Ltd.","cite":"405 F.3d 582","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/405/582/","by":{"2":"45"}},{"t":"case","label":"Fox v. Capital Co.","cite":"96 F.2d 684","y":1938,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/96/684/","by":{"2":"22"}},{"t":"case","label":"FTC v. Lane Labs-USA, Inc.","cite":"624 F.3d 575","y":2010,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/624/575/","by":{"2":"22"}},{"t":"case","label":"Georgia Power Co. v. NLRB","cite":"484 F.3d 1288","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/484/1288/","by":{"2":"22"}},{"t":"case","label":"Grace v. Center for Auto Safety","cite":"72 F.3d 1236","y":1996,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/72/1236/","by":{"2":"21, 22"}},{"t":"case","label":"Illinois Migrant Council v. Pilliod","cite":"540 F.2d 1062","y":1976,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/540/1062/","by":{"2":"26"}},{"t":"case","label":"Imageware, Inc. v. U.S. W. Comm’ns","cite":"219 F.3d 793","y":2000,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/219/793/","by":{"2":"21"}},{"t":"case","label":"Inmates of Allegheny Cty. Jail v. Wecht","cite":"754 F.2d 120","y":1985,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/754/120/","by":{"2":"23"}},{"t":"case","label":"International Union, United Mine Workers of Am. v. Bagwell","cite":"512 U.S. 821","y":1994,"id":"1993/92-1625","sc":1,"sum":"The Supreme Court unanimously held that they had been intended to punish the union, not merely to maintain order or respect for the judiciary, and that the union was therefore entitled to the heightened protections of a criminal proceeding, such as a jury trial.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Johnson v. Home State Bank","cite":"501 U.S. 78","y":1991,"id":"1990/90-693","sc":1,"sum":"After petitioner Johnson defaulted on promissory notes secured with a mortgage on his farm, respondent Home State Bank (Bank) began foreclosure proceedings in state court. While foreclosure proceedings were pending, Johnson filed for liquidation under Chapter 7 of the Bankruptcy Code, and the Bankruptcy Court discharged him from personal liability on the notes. However, because the Bank's right to proceed against …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17, 18, 40"}},{"t":"case","label":"King v. Allied Vision, Ltd.","cite":"65 F.3d 1051","y":1995,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/65/1051/","by":{"2":"22"}},{"t":"case","label":"Law v. Siegel","cite":"571 U.S. 415","y":2014,"id":"2013/12-5196","sc":1,"sum":"The Court found that a bankruptcy court may not enforce specific statutory exceptions.","sumSrc":"Oyez","by":{"2":"17","3":"11"}},{"t":"case","label":"Leman v. Krentler-Arnold Hinge Last Co.","cite":"284 U.S. 448","y":1932,"id":"scdb/1931-129","sc":1,"by":{"2":"18"}},{"t":"case","label":"Lopez v. Davis","cite":"531 U.S. 230","y":2001,"id":"2000/99-7504","sc":1,"sum":"The Court held that the categorically denial of early release to a prisoner who committed felony using firearm is a permissible exercise of the BOP's discretion, even if the prisoner has successfully completed a substance abuse program. \"The Bureau reasonably concluded that an inmate's prior involvement with firearms, in connection with the commission of a felony, suggests his readiness to resort to life-endangering violence and therefore appropriately determines the early release decision,\" wrote Justice Ginsburg for the majority.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Maggio v. Zeitz","cite":"333 U.S. 56","y":1948,"id":"scdb/1947-035","sc":1,"sum":"1. In a civil contempt proceeding against a bankrupt for failure to comply with an order to turn over to the trustee assets of the estate found to be in his possession or under his control at the time such order was issued (20 months earlier in this case), the bankruptcy court should not adjudge the bankrupt in contempt and commit him to jail to coerce compliance if it appears that he is presently unable to …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"passim"}},{"t":"case","label":"Maness v. Meyers","cite":"419 U.S. 449","y":1975,"id":"1974/73-689","sc":1,"ar":1,"sum":"Chief Justice Warren E. Burger wrote the unanimous majority opinion, holding that Maness could not be held in contempt for giving advice in good faith. The Supreme Court rejected the argument that the client should have produced the magazines and then appealed the decision to let them in as evidence.","sumSrc":"Oyez","by":{"2":"17, 26"}},{"t":"case","label":"Merrimack River Sav. Bank v. City of Clay Ctr.","cite":"219 U.S. 527","y":1911,"id":"scdb/1910-081","sc":1,"sum":"The force and effect of a decree dismissing a bill and discharging an injunction is neither suspended nor annulled as a mere consequence of an appeal to this court, even if supersedeas is allowed; but the Circuit Court has power kv continue an injunction during such an appeal by virtue of its inherent equity power. Equity Rule 93.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"25"}},{"t":"case","label":"Midland Funding, LLC v. Johnson","cite":"137 S. Ct. 1407","y":2017,"id":"2016/16-348","sc":1,"sum":"The Court determined that the Fair Debt Collection Practices Act (FDCPA) does not prevent a creditor from filing a proof of claim on an unpaid debt in a Chapter 13 bankruptcy proceeding even after the statute of limitations on that debt has run.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"Mitchell v. Helena Wholesale, Inc.","cite":"163 F. Supp. 101","y":1958,"court":"E.D. Ark.","url":"https://www.courtlistener.com/c/F.%20Supp./163/101/","sum":"Noting the “serious stigma” that attaches to a contempt finding.","sumSrc":"brief:2","by":{"2":"19"}},{"t":"case","label":"Natural Gas Pipeline Co. of Am. v. Energy Gathering, Inc.","cite":"86 F.3d 464","y":1996,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/86/464/","by":{"2":"20"}},{"t":"case","label":"Newman v. Graddick","cite":"740 F.2d 1513","y":1984,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/740/1513/","by":{"2":"27"}},{"t":"case","label":"Ohlander v. Larson","cite":"114 F.3d 1531","y":1997,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/114/1531/","by":{"2":"20"}},{"t":"case","label":"Penfield Co. of Cal. v. SEC","cite":"330 U.S. 585","y":1948,"id":"scdb/1946-074","sc":1,"sum":"in a contempt proceeding for failure to comply with a court order to enforce a subpoena duces tecum issued by the Securities and Exchange Commission in aid of an investigation pursuant to § 20 (a) of the Securities Act of 1933, 48 Stat. 74, a district court adjudged the defendant guilty of contempt and imposed an unconditional fine, but refused to grant any coercive relief designed to force him to produce the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"43"}},{"t":"case","label":"Project B.A.S.I.C. v. Kemp","cite":"947 F.2d 11","y":1991,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/947/11/","by":{"2":"18, 20, 21, 41"}},{"t":"case","label":"Reliance Ins. Co. v. Mast Constr. Co.","cite":"84 F.3d 372","y":1996,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/84/372/","by":{"2":"22"}},{"t":"case","label":"SEC v. Hyatt","cite":"621 F.3d 687","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/621/687/","by":{"2":"21"}},{"t":"case","label":"Seminole Tribe of Fla. v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"2":"32"}},{"t":"case","label":"SerVaas Inc. v. Mills","cite":"661 Fed. Appx. 7","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./661/7/","by":{"2":"19"}},{"t":"case","label":"Spallone v. United States","cite":"493 U.S. 265","y":1990,"id":"1989/88-854","sc":1,"sum":"In the circumstances of this case, the portion of the District Court's July 26 order imposing contempt sanctions against petitioner individual councilmembers if they failed to vote in favor of the ordinance was an abuse of discretion under traditional equitable principles. Petitioners were never parties to the action, nor were they found to be individually liable for any of the violations upon which the remedial …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19, 40"}},{"t":"case","label":"Spectra Sonics Aviation, Inc. v. Ogden City","cite":"931 F.2d 63","y":1991,"court":"10th Cir. Apr. 19","url":"https://www.courtlistener.com/c/F.2d/931/63/","by":{"2":"27"}},{"t":"case","label":"Thigpen v. Roberts","cite":"468 U.S. 27","y":1984,"id":"1983/82-1330","sc":1,"sum":"Following an accident in which he lost control of his car and collided with a pickup truck, killing a passenger in the truck, respondent was charged with four misdemeanors-reckless driving, driving while his license was revoked, driving on the wrong side of the road, and driving while intoxicated. Upon being convicted of these charges in a Mississippi Justice of the Peace Court, he appealed, and the case was …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"49"}},{"t":"case","label":"Vertex Distrib., Inc. v. Falcon Foam Plastics, Inc.","cite":"689 F.2d 885","y":1982,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/689/885/","by":{"2":"27"}},{"t":"case","label":"Whitehouse v. LaRoche","cite":"277 F.3d 568","y":2002,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/277/568/","by":{"2":"45","3":"10"}},{"t":"usc","label":"11 U.S.C. § 521","url":"https://www.law.cornell.edu/uscode/text/11/521","subs":["(i)(4)"],"by":{"2":"30"}},{"t":"usc","label":"11 U.S.C. § 548","url":"https://www.law.cornell.edu/uscode/text/11/548","subs":["(c)"],"by":{"2":"30"}},{"t":"usc","label":"11 U.S.C. § 550","url":"https://www.law.cornell.edu/uscode/text/11/550","subs":["(b)"],"by":{"2":"30"}},{"t":"usc","label":"11 U.S.C. § 707","url":"https://www.law.cornell.edu/uscode/text/11/707","subs":["(b)"],"by":{"2":"43"}},{"t":"usc","label":"11 U.S.C. § 901","url":"https://www.law.cornell.edu/uscode/text/11/901","by":{"2":"3"}},{"t":"usc","label":"11 U.S.C. § 944","url":"https://www.law.cornell.edu/uscode/text/11/944","by":{"2":"3"}},{"t":"usc","label":"11 U.S.C. § 1129","url":"https://www.law.cornell.edu/uscode/text/11/1129","subs":["(a)(3)"],"by":{"2":"30"}},{"t":"usc","label":"11 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/11/1225","subs":["(a)(3)"],"by":{"2":"30"}},{"t":"usc","label":"11 U.S.C. § 1325","url":"https://www.law.cornell.edu/uscode/text/11/1325","subs":["(a)(3)"],"by":{"2":"30"}},{"t":"usc","label":"18 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/18/401","by":{"2":"19"}},{"t":"rule","label":"Fed. R. Civ. P. 8","url":"https://www.law.cornell.edu/rules/frcp/rule_8","subs":["(c)(1)"],"by":{"2":"46"}},{"t":"rule","label":"Fed. R. Civ. P. 11","url":"https://www.law.cornell.edu/rules/frcp/rule_11","by":{"2":"31"}},{"t":"rule","label":"Fed. R. Civ. P. 65","url":"https://www.law.cornell.edu/rules/frcp/rule_65","subs":["(d)"],"by":{"2":"27"}},{"t":"case","label":"NBA Props., Inc. v. Gold","cite":"895 F.2d 30","y":1990,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/895/30/","by":{"3":"11"}},{"t":"case","label":"Roadway Express, Inc. v. Piper","cite":"447 U.S. 752","y":1980,"id":"1979/79-701","sc":1,"sum":"Respondents were counsel for the plaintiffs in a civil rights class action in Federal District Court against petitioner alleging that its employment policies discriminated on the basis of race. Because respondents failed to comply with orders relating to discovery and the filing of briefs, petitioner moved to dismiss the suit and requested an award of attorney's fees and court costs under Federal Rule of Civil …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"11"}},{"t":"case","label":"Wiggins v. Smith","cite":"539 U.S. 510","y":2003,"id":"2002/02-311","sc":1,"sum":"The Court held that the performance of Wiggins's attorneys at sentencing violated his Sixth Amendment right to effective assistance of counsel.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"Xitronix v. KLA-Tencor Corp.","cite":"916 F.3d 429","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/916/429/","by":{"3":"20"}}]};